def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Find rows containing horizontal bars.
    horizontal_rows = []
    for r, row in enumerate(out):
        if sum(v != 0 for v in row) < 3:
            continue
        if any(row[c] != 0 and row[c] == row[c + 1]
               for c in range(w - 1)):
            horizontal_rows.append(r)

    if not horizontal_rows:
        return out

    # Fill gaps within each horizontal bar when both ends have the same color.
    for r in horizontal_rows:
        c = 0
        while c < w:
            if out[r][c] != 0:
                c += 1
                continue
            start = c
            while c < w and out[r][c] == 0:
                c += 1
            if start > 0 and c < w and out[r][start - 1] == out[r][c]:
                color = out[r][start - 1]
                for k in range(start, c):
                    out[r][k] = color

    last_bar = max(horizontal_rows)

    # Vertical marker columns below the bars extend upward through the gaps.
    for c in range(w):
        marker_colors = [grid[r][c] for r in range(last_bar + 1, h)
                         if grid[r][c] != 0]
        if not marker_colors:
            continue
        marker = max(set(marker_colors), key=marker_colors.count)

        seeds = [(r, out[r][c]) for r in horizontal_rows if out[r][c] != 0]
        if not seeds:
            continue

        first_r, first_color = seeds[0]
        for r in range(first_r + 1):
            out[r][c] = first_color

        for (r1, _), (r2, color) in zip(seeds, seeds[1:]):
            for r in range(r1 + 1, r2 + 1):
                out[r][c] = color

        final_r, final_color = seeds[-1]
        for r in range(final_r + 1, last_bar + 1):
            out[r][c] = final_color
        for r in range(last_bar + 1, h):
            out[r][c] = marker

    return out
